      .from("my_concepts")
      .select(CONCEPT_COLUMNS_WITH_SLOTS)
      .neq("space_id", currentSpaceId)
      .eq("is_schema", false)
      .eq("is_relation", false),
    client
      .from("my_contents")
      .select(DIRECT_CONTENT_COLUMNS)
      .neq("space_id", currentSpaceId)
